/**
 * Crafty Rose Social Studio — server entry points.
 *
 * Phase 1: serves the app shell, sets up the database spreadsheet and
 * returns dashboard data (clearly flagged as SAMPLE until real
 * platform connections exist in Phase 3).
 */

var APP = {
  name: 'Crafty Rose Social Studio',
  version: '0.4.0',
  timeZone: 'America/Halifax',
  siteUrl: 'https://studio.craftyrosegifts.ca'
};

/** Web app entry point. */
function doGet() {
  var tpl = HtmlService.createTemplateFromFile('Index');
  tpl.siteUrl = APP.siteUrl;
  return tpl.evaluate()
    .setTitle(APP.name)
    .setFaviconUrl(APP.siteUrl + '/rose64.png')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.DEFAULT);
}

/** Lets HTML templates pull in other HTML files: <?!= include('Styles') ?> */
function include(name) {
  return HtmlService.createHtmlOutputFromFile(name).getContent();
}

/**
 * Called by the interface on load. Makes sure the database exists,
 * then returns everything the shell and dashboard need.
 */
function getAppBootstrap() {
  var db = Db.ensure();
  return {
    app: { name: APP.name, version: APP.version, timeZone: APP.timeZone },
    user: { email: Session.getActiveUser().getEmail() },
    database: { url: db.getUrl(), ready: true },
    now: new Date().toISOString(),
    dashboard: SampleData.dashboard(),
    posts: studioSummary_()
  };
}

/** Run once from the editor (or let the app call it) to create the database. */
function setup() {
  var db = Db.ensure();
  Logger.log('Database ready: ' + db.getUrl());
}

/** Real post counts and the next scheduled posts (used by the dashboard and sidebar). */
function studioSummary_() {
  var posts = listPosts();
  var scheduled = posts.filter(function (p) { return p.status === 'scheduled'; });
  return {
    counts: {
      scheduled: scheduled.length,
      drafts: posts.filter(function (p) { return p.status === 'draft'; }).length,
      media: Db.all('Media').length
    },
    upcoming: scheduled.slice(0, 5)
  };
}

/** Lightweight refresh for the sidebar counts and dashboard after saving. */
function getStudioSummary() { return studioSummary_(); }

/**
 * Crafty Rose Social Studio — social account connections (Phase 3).
 *
 * Meta (Instagram + Facebook) uses the official Graph API with OAuth ("Facebook Login").
 * Security:
 *  - The App Secret and all access tokens live in Script Properties (private to the
 *    script owner). They are NEVER written to the spreadsheet or sent to the browser.
 *  - The Accounts tab only stores public info (page name, @username, ids, status).
 */

var META = {
  version: 'v26.0',
  graph: 'https://graph.facebook.com/v26.0/',
  dialog: 'https://www.facebook.com/v26.0/dialog/oauth',
  scopes: [
    'public_profile', 'business_management', 'pages_show_list', 'pages_read_engagement',
    'pages_manage_posts', 'read_insights', 'instagram_basic', 'instagram_content_publish',
    'instagram_manage_insights'
  ]
};

var Secrets = (function () {
  function p() { return PropertiesService.getScriptProperties(); }
  return {
    get: function (k) { return p().getProperty(k) || ''; },
    set: function (k, v) { if (v === null || v === undefined || v === '') p().deleteProperty(k); else p().setProperty(k, String(v)); },
    json: function (k, fb) { try { return JSON.parse(p().getProperty(k) || '') || fb; } catch (e) { return fb; } }
  };
})();

/** The exact address Meta must send people back to (paste into the Meta app settings). */
function oauthRedirectUri_() {
  return 'https://script.google.com/macros/d/' + ScriptApp.getScriptId() + '/usercallback';
}

/** Small Graph API helper. Throws a friendly error with Meta's message. */
function metaApi_(method, path, params, opts) {
  opts = opts || {};
  var url = /^https?:/.test(path) ? path : META.graph + path;
  var options = { method: method, muteHttpExceptions: true, headers: opts.headers || {} };
  params = params || {};
  if (method === 'get') {
    var q = Object.keys(params).filter(function (k) { return params[k] !== undefined && params[k] !== ''; })
      .map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]); }).join('&');
    if (q) url += (url.indexOf('?') === -1 ? '?' : '&') + q;
  } else if (opts.body !== undefined) {
    options.payload = opts.body;
    if (opts.contentType) options.contentType = opts.contentType;
  } else {
    var clean = {};
    Object.keys(params).forEach(function (k) { if (params[k] !== undefined && params[k] !== '') clean[k] = params[k]; });
    options.payload = clean;
  }
  var res = UrlFetchApp.fetch(url, options);
  var text = res.getContentText();
  var data;
  try { data = text ? JSON.parse(text) : {}; } catch (e) { data = { raw: text }; }
  if (res.getResponseCode() >= 300 || data.error) {
    var err = data.error || {};
    var e2 = new Error(friendlyMetaError_(err, res.getResponseCode(), text));
    e2.metaCode = err.code; e2.metaSub = err.error_subcode; e2.transient = !!err.is_transient || res.getResponseCode() >= 500;
    throw e2;
  }
  return data;
}

function friendlyMetaError_(err, http, text) {
  var msg = err.error_user_msg || err.message || ('HTTP ' + http + ' ' + String(text || '').slice(0, 200));
  if (err.code === 190) return 'Your Meta connection has expired or was removed. Reconnect Instagram & Facebook in Social Accounts. (' + msg + ')';
  if (err.code === 10 || err.code === 200) return 'Meta says the app doesn’t have permission for this. Reconnect and make sure every permission is ticked. (' + msg + ')';
  if (err.code === 4 || err.code === 17 || err.code === 32 || err.code === 613) return 'Meta rate limit reached — the studio will try again later. (' + msg + ')';
  if (err.code === 9 && err.error_subcode === 2207042) return 'Instagram’s daily publishing limit was reached. The studio will retry later.';
  return msg;
}

/* ------------------------------------------------------------------ */
/* Status for the Social Accounts page                                 */
/* ------------------------------------------------------------------ */

function getConnections() {
  Db.ensure();
  var appId = Secrets.get('META_APP_ID');
  var pages = Secrets.json('META_PAGES', []);
  var pageId = Secrets.get('META_PAGE_ID');
  var page = pages.filter(function (p) { return p.id === pageId; })[0] || null;
  var exp = Number(Secrets.get('META_USER_TOKEN_EXP') || 0);
  var accounts = Db.all('Accounts').map(function (a) {
    return { id: a.id, platform: a.platform, accountName: a.accountName, username: a.username, externalId: String(a.externalId || ''),
      status: a.status, connectedAt: String(a.connectedAt || ''), lastSyncAt: String(a.lastSyncAt || ''), lastError: a.lastError || '', picture: a.notes || '' };
  });
  return {
    redirectUri: oauthRedirectUri_(),
    privacyUrl: APP.siteUrl + '/privacy.html',
    termsUrl: APP.siteUrl + '/terms.html',
    siteDomain: APP.siteUrl.replace(/^https?:\/\//, ''),
    meta: {
      appConfigured: !!(appId && Secrets.get('META_APP_SECRET')),
      appId: appId,                 // the App ID is public information; the secret is never returned
      connected: !!(page && Secrets.get('META_USER_TOKEN')),
      userName: Secrets.get('META_USER_NAME'),
      tokenExpires: exp ? new Date(exp).toISOString() : '',
      pages: pages.map(function (p) { return { id: p.id, name: p.name, picture: p.picture, ig: p.ig ? { id: p.ig.id, username: p.ig.username } : null }; }),
      pageId: pageId,
      scopes: META.scopes
    },
    accounts: accounts,
    publisher: publisherStatus_()
  };
}

/** Save the Meta App ID + App Secret (entered by the owner in Social Accounts). */
function saveMetaApp(appId, appSecret) {
  appId = String(appId || '').trim();
  appSecret = String(appSecret || '').trim();
  if (!/^\d{6,25}$/.test(appId)) throw new Error('The App ID should be a long number (find it in Meta › App settings › Basic).');
  if (appSecret && !/^[a-f0-9]{32}$/i.test(appSecret)) throw new Error('That doesn’t look like an App Secret (32 letters and numbers). Click “Show” next to App Secret in Meta and copy it again.');
  if (!appSecret && !Secrets.get('META_APP_SECRET')) throw new Error('Paste the App Secret too.');
  Secrets.set('META_APP_ID', appId);
  if (appSecret) Secrets.set('META_APP_SECRET', appSecret);
  Db.log('info', 'account', 'Saved Meta app settings (App ID ' + appId + ')', { platform: 'facebook' });
  return getConnections();
}

/** URL that starts "Connect Instagram & Facebook". Opened in a new tab by the interface. */
function getMetaAuthUrl() {
  var appId = Secrets.get('META_APP_ID');
  if (!appId || !Secrets.get('META_APP_SECRET')) throw new Error('Add your Meta App ID and App Secret first (step 2).');
  var state = ScriptApp.newStateToken().withMethod('metaAuthCallback').withTimeout(900).createToken();
  var q = {
    client_id: appId, redirect_uri: oauthRedirectUri_(), state: state, response_type: 'code',
    scope: META.scopes.join(','), auth_type: 'rerequest'
  };
  return META.dialog + '?' + Object.keys(q).map(function (k) { return k + '=' + encodeURIComponent(q[k]); }).join('&');
}

/** Meta sends the person back here after they approve (via /usercallback). */
function metaAuthCallback(request) {
  var p = (request && request.parameter) || {};
  try {
    if (p.error) throw new Error(p.error_description || p.error_reason || p.error);
    if (!p.code) throw new Error('Meta didn’t send an approval code. Please try connecting again.');
    var appId = Secrets.get('META_APP_ID'), secret = Secrets.get('META_APP_SECRET');
    var short = metaApi_('get', 'oauth/access_token', { client_id: appId, client_secret: secret, redirect_uri: oauthRedirectUri_(), code: p.code });
    var long = metaApi_('get', 'oauth/access_token', { grant_type: 'fb_exchange_token', client_id: appId, client_secret: secret, fb_exchange_token: short.access_token });
    var userToken = long.access_token || short.access_token;
    var expiresIn = Number(long.expires_in || short.expires_in || 60 * 86400);
    var me = metaApi_('get', 'me', { fields: 'id,name', access_token: userToken });
    Secrets.set('META_USER_TOKEN', userToken);
    Secrets.set('META_USER_TOKEN_EXP', String(Date.now() + expiresIn * 1000));
    Secrets.set('META_USER_ID', me.id);
    Secrets.set('META_USER_NAME', me.name);
    var pages = loadMetaPages_(userToken);
    if (!pages.length) throw new Error('No Facebook Pages were shared with the studio. Connect again and make sure your Crafty Rose Gifts Page (and its Instagram account) are ticked.');
    var keep = Secrets.get('META_PAGE_ID');
    var choice = pages.filter(function (x) { return x.id === keep; })[0] || (pages.length === 1 ? pages[0] : pages.filter(function (x) { return x.ig; })[0]);
    if (choice) selectMetaPage_(choice.id);
    Db.log('success', 'account', 'Connected Meta as ' + me.name + ' (' + pages.length + ' Page' + (pages.length === 1 ? '' : 's') + ')', { platform: 'facebook' });
    ensurePublisherTrigger_();
    return callbackPage_(true, 'Instagram & Facebook are connected', choice ?
      'Connected to the Facebook Page “' + choice.name + '”' + (choice.ig ? ' and Instagram @' + choice.ig.username : ' (no Instagram account is linked to this Page)') + '.' :
      'Go back to the studio to choose which Page to use.');
  } catch (e) {
    Db.log('error', 'account', 'Meta connection failed: ' + e.message, { platform: 'facebook' });
    return callbackPage_(false, 'Couldn’t connect', e.message);
  }
}

function loadMetaPages_(userToken) {
  var res = metaApi_('get', 'me/accounts', {
    fields: 'id,name,access_token,tasks,picture{url},instagram_business_account{id,username,name,profile_picture_url,followers_count}',
    limit: 100, access_token: userToken
  });
  var pages = (res.data || []).map(function (pg) {
    var ig = pg.instagram_business_account;
    return {
      id: pg.id, name: pg.name, token: pg.access_token, tasks: pg.tasks || [],
      picture: pg.picture && pg.picture.data ? pg.picture.data.url : '',
      ig: ig ? { id: ig.id, username: ig.username, name: ig.name, picture: ig.profile_picture_url || '', followers: ig.followers_count || 0 } : null
    };
  });
  Secrets.set('META_PAGES', JSON.stringify(pages));
  return pages;
}

/** Pick which Facebook Page (and its linked Instagram) the studio posts to. */
function selectMetaPage(pageId) { selectMetaPage_(pageId); return getConnections(); }

function selectMetaPage_(pageId) {
  var pages = Secrets.json('META_PAGES', []);
  var pg = pages.filter(function (x) { return x.id === pageId; })[0];
  if (!pg) throw new Error('That Page isn’t available. Reconnect and tick it.');
  Secrets.set('META_PAGE_ID', pg.id);
  Db.withLock(function () {
    Db.removeWhere('Accounts', 'platform', 'facebook');
    Db.removeWhere('Accounts', 'platform', 'instagram');
    var now = new Date().toISOString();
    Db.insert('Accounts', { platform: 'facebook', accountName: pg.name, username: pg.name, externalId: pg.id, status: 'connected',
      scopes: META.scopes.join(' '), capabilities: { publish: true }, connectedAt: now, lastSyncAt: now, notes: pg.picture });
    if (pg.ig) {
      Db.insert('Accounts', { platform: 'instagram', accountName: pg.ig.name || pg.ig.username, username: pg.ig.username, externalId: pg.ig.id, status: 'connected',
        scopes: META.scopes.join(' '), capabilities: { publish: true }, connectedAt: now, lastSyncAt: now, notes: pg.ig.picture });
    }
  });
}

/** Re-check the connection (token still valid? Instagram still linked?). */
function testMetaConnection() {
  var token = Secrets.get('META_USER_TOKEN');
  if (!token) throw new Error('Not connected yet.');
  try {
    loadMetaPages_(token);
    var id = Secrets.get('META_PAGE_ID');
    if (id) selectMetaPage_(id);
    Db.log('success', 'account', 'Meta connection checked — all good', { platform: 'facebook' });
  } catch (e) {
    Db.withLock(function () {
      Db.all('Accounts').filter(function (a) { return a.platform === 'facebook' || a.platform === 'instagram'; })
        .forEach(function (a) { Db.update('Accounts', a.id, { status: 'error', lastError: e.message }); });
    });
    throw e;
  }
  return getConnections();
}

/** Disconnect: forget all Meta tokens (the App ID/Secret can be kept for reconnecting). */
function disconnectMeta(forgetApp) {
  var token = Secrets.get('META_USER_TOKEN');
  if (token) {
    try { metaApi_('delete', 'me/permissions', {}, { body: { access_token: token } }); } catch (e) { /* already revoked */ }
  }
  ['META_USER_TOKEN', 'META_USER_TOKEN_EXP', 'META_USER_ID', 'META_USER_NAME', 'META_PAGES', 'META_PAGE_ID'].forEach(function (k) { Secrets.set(k, ''); });
  if (forgetApp) { Secrets.set('META_APP_ID', ''); Secrets.set('META_APP_SECRET', ''); }
  Db.withLock(function () {
    Db.removeWhere('Accounts', 'platform', 'facebook');
    Db.removeWhere('Accounts', 'platform', 'instagram');
  });
  Db.log('info', 'account', 'Disconnected Instagram & Facebook', { platform: 'facebook' });
  return getConnections();
}

/** Tokens the publisher needs (server-only). */
function metaCreds_() {
  var pages = Secrets.json('META_PAGES', []);
  var pg = pages.filter(function (x) { return x.id === Secrets.get('META_PAGE_ID'); })[0];
  if (!pg) return null;
  return { pageId: pg.id, pageToken: pg.token, igId: pg.ig ? pg.ig.id : '', userToken: Secrets.get('META_USER_TOKEN'), appId: Secrets.get('META_APP_ID') };
}

/** Which platforms can publish right now. */
function connectedPlatforms_() {
  var c = metaCreds_(), out = {};
  if (c) { out.facebook = true; if (c.igId) out.instagram = true; }
  return out;
}

function callbackPage_(ok, title, message) {
  var html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600&display=swap" rel="stylesheet">' +
    '<style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#F4F8F5;font-family:"Plus Jakarta Sans",system-ui,sans-serif;color:#2C3832}' +
    '.c{background:#fff;border:1px solid #E4ECE7;border-radius:18px;padding:32px 28px;max-width:440px;margin:16px;text-align:center;box-shadow:0 10px 30px rgba(76,109,94,.08)}' +
    '.i{width:56px;height:56px;border-radius:50%;display:grid;place-items:center;margin:0 auto 14px;font-size:28px;color:#fff;background:' + (ok ? '#4C6D5E' : '#A8464C') + '}' +
    'h1{font-size:20px;margin:0 0 8px}p{color:#4E5C55;line-height:1.5;margin:0 0 18px}.s{font-size:13px;color:#74827A}</style></head><body><div class="c">' +
    '<div class="i">' + (ok ? '✓' : '!') + '</div><h1>' + escHtml_(title) + '</h1><p>' + escHtml_(message) + '</p>' +
    '<p class="s">You can close this tab and go back to Crafty Rose Social Studio' + (ok ? ' — it will update on its own.' : ', then try again.') + '</p></div></body></html>';
  return HtmlService.createHtmlOutput(html).setTitle(title);
}

function escHtml_(s) { return String(s || '').replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }

/**
 * Crafty Rose Social Studio — database layer.
 *
 * Application data lives in a private Google Sheet ("Crafty Rose Studio — Data")
 * inside the "Crafty Rose Social Studio" Drive folder. One tab per table.
 *
 * Security: access tokens are NEVER written to the spreadsheet. They are kept in
 * Apps Script's private property store (see Phase 3), which only this script can read.
 */

var DB_SCHEMA = {
  Posts: [
    'id', 'title', 'postType', 'status', 'baseCaption', 'baseHashtags', 'link',
    'mediaIds', 'platforms', 'scheduledAt', 'timeZone', 'inQueue', 'notes', 'createdAt', 'updatedAt'
  ],
  // One row per platform for each post, so every platform has its own caption,
  // settings and publishing status (e.g. Instagram published, TikTok failed → retry TikTok only).
  PostTargets: [
    'id', 'postId', 'platform', 'accountId', 'format', 'caption', 'hashtags', 'title',
    'description', 'destinationUrl', 'coverMediaId', 'mediaIds', 'options', 'status',
    'scheduledAt', 'publishedAt', 'platformPostId', 'platformUrl', 'attempts',
    'lastError', 'lastAttemptAt', 'createdAt', 'updatedAt', 'pubState'
  ],
  Media: [
    'id', 'fileName', 'driveFileId', 'folder', 'tags', 'kind', 'mimeType', 'sizeBytes',
    'width', 'height', 'aspectRatio', 'durationSec', 'container', 'videoCodec',
    'audioCodec', 'frameRate', 'thumbnailFileId', 'compatibility', 'parentMediaId',
    'isOriginal', 'uploadedAt', 'notes', 'driveFolderId', 'thumbData', 'bitrate', 'rotation',
    'moovAtFront', 'hasEditList', 'imageFormat'
  ],
  Accounts: [
    'id', 'platform', 'accountName', 'username', 'externalId', 'status', 'scopes',
    'capabilities', 'connectedAt', 'lastSyncAt', 'lastError', 'notes'
  ],
  Captions: [
    'id', 'title', 'category', 'body', 'hashtagGroupId', 'platforms', 'timesUsed',
    'createdAt', 'updatedAt'
  ],
  HashtagGroups: ['id', 'name', 'category', 'hashtags', 'createdAt', 'updatedAt'],
  AccountMetrics: [
    'id', 'date', 'platform', 'accountId', 'followers', 'reach', 'views', 'engagements',
    'likes', 'comments', 'shares', 'saves', 'videoViews', 'capturedAt'
  ],
  PostMetrics: [
    'id', 'targetId', 'platform', 'capturedAt', 'views', 'reach', 'likes', 'comments',
    'shares', 'saves', 'videoViews', 'watchTimeSec'
  ],
  ActivityLog: [
    'id', 'timestamp', 'level', 'type', 'postId', 'targetId', 'platform', 'message', 'details'
  ],
  Settings: ['key', 'value', 'updatedAt']
};

var MEDIA_FOLDERS = [
  'Product Photography', 'Tumblers and Drinkware', 'Apparel', 'Personalized Gifts',
  'Seasonal Products', 'Christmas', 'Behind the Scenes', 'Videos and Reels',
  'General Marketing'
];

var DEFAULT_SETTINGS = {
  timeZone: 'America/Halifax',
  brandLightGreen: '#8BC4A9',
  brandDarkGreen: '#4C6D5E',
  defaultPublishTime: '10:00',
  queueSlots: '[{"day":2,"time":"10:00"},{"day":4,"time":"18:30"},{"day":6,"time":"10:00"}]',
  schemaVersion: '1'
};

var Db = (function () {
  var PROP_DB = 'DB_SPREADSHEET_ID';
  var PROP_ROOT = 'DRIVE_ROOT_FOLDER_ID';
  var cached = null;

  function props() { return PropertiesService.getScriptProperties(); }

  function tryOpen(id) {
    if (!id) return null;
    try { return SpreadsheetApp.openById(id); } catch (e) { return null; }
  }

  // Drive access uses the Drive REST API with the narrow "drive.file" permission,
  // so the studio can only see the files and folders it created itself.
  var Drive = {
    req: function (method, path, body, query) {
      var url = 'https://www.googleapis.com/drive/v3/' + path;
      if (query) {
        url += '?' + Object.keys(query).map(function (k) {
          return encodeURIComponent(k) + '=' + encodeURIComponent(query[k]);
        }).join('&');
      }
      var res = UrlFetchApp.fetch(url, {
        method: method,
        contentType: 'application/json',
        payload: body ? JSON.stringify(body) : undefined,
        headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() },
        muteHttpExceptions: true
      });
      var code = res.getResponseCode();
      if (code >= 300) throw new Error('Drive API ' + code + ': ' + res.getContentText().slice(0, 300));
      var text = res.getContentText();
      return text ? JSON.parse(text) : {};
    },
    exists: function (id) {
      if (!id) return false;
      try { return !Drive.req('get', 'files/' + id, null, { fields: 'id,trashed' }).trashed; }
      catch (e) { return false; }
    },
    folder: function (name, parentId) {
      var q = "mimeType='application/vnd.google-apps.folder' and trashed=false and name='" +
        name.replace(/'/g, "\\'") + "'" + (parentId ? " and '" + parentId + "' in parents" : '');
      var found = Drive.req('get', 'files', null, { q: q, fields: 'files(id)', pageSize: 1 }).files;
      if (found && found.length) return found[0].id;
      var body = { name: name, mimeType: 'application/vnd.google-apps.folder' };
      if (parentId) body.parents = [parentId];
      return Drive.req('post', 'files', body, { fields: 'id' }).id;
    },
    move: function (fileId, parentId) {
      var cur = Drive.req('get', 'files/' + fileId, null, { fields: 'parents' }).parents || [];
      Drive.req('patch', 'files/' + fileId, {}, { addParents: parentId, removeParents: cur.join(','), fields: 'id' });
    },
    copy: function (fileId, name, parentId) {
      return Drive.req('post', 'files/' + fileId + '/copy', { name: name, parents: [parentId] }, { fields: 'id' }).id;
    },
    children: function (parentId) {
      return Drive.req('get', 'files', null, {
        q: "'" + parentId + "' in parents and trashed=false",
        fields: 'files(id,name,createdTime)', orderBy: 'createdTime desc', pageSize: 100
      }).files || [];
    },
    trash: function (fileId) { Drive.req('patch', 'files/' + fileId, { trashed: true }, { fields: 'id' }); }
  };

  /** Creates (once) the studio's Drive folders and returns their IDs. */
  function ensureFolders() {
    var p = props();
    var rootId = p.getProperty(PROP_ROOT);
    var version = 'v2:' + MEDIA_FOLDERS.length;
    if (p.getProperty('DRIVE_FOLDERS_READY') === version && Drive.exists(rootId)) {
      return {
        root: rootId,
        backups: p.getProperty('DRIVE_BACKUPS_FOLDER_ID'),
        media: p.getProperty('DRIVE_MEDIA_FOLDER_ID'),
        mediaFolders: JSON.parse(p.getProperty('DRIVE_MEDIA_SUBFOLDERS') || '{}')
      };
    }
    if (!Drive.exists(rootId)) {
      rootId = Drive.folder('Crafty Rose Social Studio', null);
      p.setProperty(PROP_ROOT, rootId);
    }
    var backups = Drive.folder('Backups', rootId);
    var media = Drive.folder('Media Library', rootId);
    var sub = {};
    MEDIA_FOLDERS.forEach(function (name) { sub[name] = Drive.folder(name, media); });
    p.setProperties({
      DRIVE_BACKUPS_FOLDER_ID: backups,
      DRIVE_MEDIA_FOLDER_ID: media,
      DRIVE_MEDIA_SUBFOLDERS: JSON.stringify(sub),
      DRIVE_FOLDERS_READY: version
    });
    return { root: rootId, backups: backups, media: media, mediaFolders: sub };
  }

  function ensureSheets(ss) {
    Object.keys(DB_SCHEMA).forEach(function (name) {
      var headers = DB_SCHEMA[name];
      var sh = ss.getSheetByName(name) || ss.insertSheet(name);
      var current = sh.getLastColumn() > 0
        ? sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0] : [];
      // Add any missing columns at the end (safe schema upgrades, never deletes data).
      var missing = headers.filter(function (h) { return current.indexOf(h) === -1; });
      if (current.length === 0) {
        sh.getRange(1, 1, 1, headers.length).setValues([headers]);
      } else if (missing.length) {
        sh.getRange(1, current.length + 1, 1, missing.length).setValues([missing]);
      }
      var width = Math.max(current.length + missing.length, headers.length);
      sh.getRange(1, 1, 1, width)
        .setFontWeight('bold').setBackground('#EAF3EE').setFontColor('#3D5A4D');
      sh.setFrozenRows(1);
    });
    var stray = ss.getSheetByName('Sheet1');
    if (stray && ss.getSheets().length > 1) ss.deleteSheet(stray);
  }

  function ensureSettings(ss) {
    var sh = ss.getSheetByName('Settings');
    var rows = sh.getLastRow() > 1 ? sh.getRange(2, 1, sh.getLastRow() - 1, 1).getValues() : [];
    var keys = rows.map(function (r) { return r[0]; });
    var now = new Date().toISOString();
    Object.keys(DEFAULT_SETTINGS).forEach(function (k) {
      if (keys.indexOf(k) === -1) sh.appendRow([k, DEFAULT_SETTINGS[k], now]);
    });
  }

  function ensure() {
    if (cached) return cached;
    var lock = LockService.getScriptLock();
    lock.waitLock(20000);
    try {
      var ss = tryOpen(props().getProperty(PROP_DB));
      if (!ss) {
        var folders = ensureFolders();
        ss = SpreadsheetApp.create('Crafty Rose Studio — Data');
        Drive.move(ss.getId(), folders.root);
        props().setProperty(PROP_DB, ss.getId());
        ss.setSpreadsheetTimeZone(APP.timeZone);
      }
      // Only touch the sheet structure when the schema has changed (keeps loading fast).
      var schemaKey = JSON.stringify(DB_SCHEMA).length + ':' + Object.keys(DB_SCHEMA).length + ':' + Object.keys(DEFAULT_SETTINGS).length;
      if (props().getProperty('DB_SCHEMA_KEY') !== schemaKey || props().getProperty('DB_SCHEMA_FOR') !== ss.getId()) {
        ensureSheets(ss);
        ensureSettings(ss);
        props().setProperties({ DB_SCHEMA_KEY: schemaKey, DB_SCHEMA_FOR: ss.getId() });
      }
      cached = ss;
      return ss;
    } finally {
      lock.releaseLock();
    }
  }

  /** Read a whole table as an array of objects. */
  function all(table) {
    var sh = ensure().getSheetByName(table);
    var last = sh.getLastRow();
    if (last < 2) return [];
    var values = sh.getRange(1, 1, last, sh.getLastColumn()).getValues();
    var headers = values.shift();
    return values.map(function (row) {
      var o = {};
      headers.forEach(function (h, i) { o[h] = cellOut(row[i]); });
      return o;
    });
  }

  /** Append a row object to a table; returns the object with id/timestamps. */
  function insert(table, obj) {
    var sh = ensure().getSheetByName(table);
    var headers = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
    var now = new Date().toISOString();
    if (headers.indexOf('id') !== -1 && !obj.id) obj.id = Utilities.getUuid();
    if (headers.indexOf('createdAt') !== -1 && !obj.createdAt) obj.createdAt = now;
    if (headers.indexOf('updatedAt') !== -1) obj.updatedAt = now;
    sh.appendRow(headers.map(function (h) { return toCell(obj[h]); }));
    return obj;
  }

  function sheetInfo(table) {
    var sh = ensure().getSheetByName(table);
    var headers = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
    return { sh: sh, headers: headers, idCol: headers.indexOf('id') };
  }

  function findRow(info, id) {
    var last = info.sh.getLastRow();
    if (last < 2) return -1;
    var ids = info.sh.getRange(2, info.idCol + 1, last - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) if (String(ids[i][0]) === String(id)) return i + 2;
    return -1;
  }

  function toCell(v) {
    if (v !== null && typeof v === 'object') return JSON.stringify(v);
    if (v === undefined || v === null) return '';
    // Stop Sheets treating text like "=..." as a formula.
    if (typeof v === 'string' && /^[=+\-@]/.test(v)) return "'" + v;
    // Stop Sheets turning text like "9:16", "4/5" or "2026-11-01" into times/dates.
    if (typeof v === 'string' && /^[\d\s:\/.\-T+Z]+$/.test(v) && /[:\/\-]/.test(v)) return "'" + v;
    return v;
  }

  /** Read one row by id. */
  function get(table, id) {
    var info = sheetInfo(table);
    var row = findRow(info, id);
    if (row < 0) return null;
    var vals = info.sh.getRange(row, 1, 1, info.headers.length).getValues()[0];
    var o = {};
    info.headers.forEach(function (h, i) { o[h] = cellOut(vals[i]); });
    return o;
  }

  /** Dates can't be sent to the browser, so always hand back ISO text. */
  function cellOut(v) { return v instanceof Date ? v.toISOString() : v; }

  /** Merge fields into an existing row. */
  function update(table, id, patch) {
    var info = sheetInfo(table);
    var row = findRow(info, id);
    if (row < 0) throw new Error(table + ' item not found');
    var range = info.sh.getRange(row, 1, 1, info.headers.length);
    var vals = range.getValues()[0];
    if (info.headers.indexOf('updatedAt') !== -1) patch.updatedAt = new Date().toISOString();
    info.headers.forEach(function (h, i) { if (h in patch && h !== 'id') vals[i] = toCell(patch[h]); });
    range.setValues([vals]);
    return get(table, id);
  }

  /** Delete rows matching a predicate on one column. */
  function removeWhere(table, column, value) {
    var info = sheetInfo(table);
    var col = info.headers.indexOf(column);
    var last = info.sh.getLastRow();
    if (col < 0 || last < 2) return 0;
    var vals = info.sh.getRange(2, col + 1, last - 1, 1).getValues();
    var n = 0;
    for (var i = vals.length - 1; i >= 0; i--) {
      if (String(vals[i][0]) === String(value)) { info.sh.deleteRow(i + 2); n++; }
    }
    return n;
  }

  function withLock(fn) {
    var lock = LockService.getScriptLock();
    lock.waitLock(20000);
    try { return fn(); } finally { lock.releaseLock(); }
  }

  /** Append an entry to the activity log. */
  function log(level, type, message, extra) {
    extra = extra || {};
    return insert('ActivityLog', {
      timestamp: new Date().toISOString(), level: level, type: type, message: message,
      postId: extra.postId || '', targetId: extra.targetId || '',
      platform: extra.platform || '', details: extra.details || ''
    });
  }

  /** Copy the database into Drive › Crafty Rose Social Studio › Backups (keeps the latest 8). */
  function backup() {
    var ss = ensure();
    var folders = ensureFolders();
    var stamp = Utilities.formatDate(new Date(), APP.timeZone, 'yyyy-MM-dd HHmm');
    var name = 'Studio backup ' + stamp;
    SpreadsheetApp.flush();
    Drive.copy(ss.getId(), name, folders.backups);
    Drive.children(folders.backups).slice(8).forEach(function (f) { Drive.trash(f.id); });
    log('success', 'backup', 'Database backed up (' + stamp + ')');
    return { ok: true, name: name };
  }

  return {
    ensure: ensure, all: all, insert: insert, get: get, update: update, removeWhere: removeWhere,
    withLock: withLock, log: log, backup: backup, folders: ensureFolders, drive: Drive
  };
})();

/** Exposed to the interface: Settings › "Back up now". */
function backupDatabase() { return Db.backup(); }

