/**
 * Crafty Rose Social Studio — Media Library (server side).
 *
 * Files are uploaded straight from the browser to Google Drive (into the
 * "Crafty Rose Social Studio › Media Library › <folder>" folders), then
 * registered here. Originals are never modified; optimized copies (Phase 5)
 * will be saved as new files linked by `parentMediaId`.
 */

var MEDIA_JSON_FIELDS = ['tags', 'compatibility'];

function parseMediaRow_(r) {
  var o = {};
  Object.keys(r).forEach(function (k) { o[k] = r[k]; });
  MEDIA_JSON_FIELDS.forEach(function (k) {
    if (typeof o[k] === 'string' && o[k]) { try { o[k] = JSON.parse(o[k]); } catch (e) { /* keep string */ } }
    if (!o[k]) o[k] = k === 'tags' ? [] : null;
  });
  ['sizeBytes', 'width', 'height', 'durationSec', 'frameRate', 'bitrate', 'rotation'].forEach(function (k) {
    var n = (o[k] === '' || o[k] === null || o[k] === undefined) ? NaN : Number(o[k]);
    o[k] = isFinite(n) ? n : null; // NaN/undefined can't be sent back to the browser
  });
  o.uploadedAt = o.uploadedAt instanceof Date ? o.uploadedAt.toISOString() : String(o.uploadedAt || '');
  // Older rows may hold an aspect ratio that Sheets turned into a time; rebuild it from the size.
  if (o.width && o.height) o.aspectRatio = '';
  Object.keys(o).forEach(function (k) { if (o[k] instanceof Date) o[k] = o[k].toISOString(); });
  return o;
}

/** Everything the browser needs to upload directly to Drive. */
function getUploadContext() {
  Db.ensure();
  var f = Db.folders();
  return {
    token: ScriptApp.getOAuthToken(),
    expiresInSec: 3000,
    folders: MEDIA_FOLDERS.map(function (name) { return { name: name, id: f.mediaFolders[name] }; })
  };
}

/** List the whole library, newest first. */
function listMedia() {
  return Db.all('Media').map(parseMediaRow_).sort(function (a, b) {
    return a.uploadedAt < b.uploadedAt ? 1 : -1;
  });
}

/** Save a newly uploaded file's details. */
function registerMedia(m) {
  Db.ensure();
  if (!m || !m.driveFileId) throw new Error('Missing Drive file');
  var allowed = DB_SCHEMA.Media;
  var row = {};
  allowed.forEach(function (k) { if (k in m) row[k] = m[k]; });
  row.uploadedAt = new Date().toISOString();
  row.isOriginal = true;
  if (row.thumbData && String(row.thumbData).length > 48000) row.thumbData = '';
  var saved = Db.withLock(function () { return Db.insert('Media', row); });
  Db.log('success', 'media', 'Uploaded “' + row.fileName + '” to ' + row.folder);
  return parseMediaRow_(saved);
}

/** Rename, re-folder, tag or annotate a media item. */
function updateMedia(id, patch) {
  Db.ensure();
  var current = Db.get('Media', id);
  if (!current) throw new Error('Media not found');
  var clean = {};
  if (patch.fileName && patch.fileName !== current.fileName) {
    clean.fileName = String(patch.fileName).slice(0, 200);
    Db.drive.req('patch', 'files/' + current.driveFileId, { name: clean.fileName }, { fields: 'id' });
  }
  if (patch.folder && patch.folder !== current.folder) {
    var folders = Db.folders().mediaFolders;
    if (!folders[patch.folder]) throw new Error('Unknown folder');
    Db.drive.move(current.driveFileId, folders[patch.folder]);
    clean.folder = patch.folder;
    clean.driveFolderId = folders[patch.folder];
  }
  if (patch.tags) clean.tags = patch.tags.map(function (t) { return String(t).trim().toLowerCase(); }).filter(String).slice(0, 30);
  if ('notes' in patch) clean.notes = String(patch.notes || '').slice(0, 2000);
  if ('compatibility' in patch) clean.compatibility = patch.compatibility;
  var saved = Db.withLock(function () { return Db.update('Media', id, clean); });
  return parseMediaRow_(saved);
}

/**
 * Move a media file to the Drive trash (recoverable for 30 days) and remove it
 * from the library. Refuses if posts still use it, unless `force` is true.
 */
function deleteMedia(id, force) {
  Db.ensure();
  var item = Db.get('Media', id);
  if (!item) return { ok: true };
  var usedBy = Db.all('Posts').filter(function (p) { return String(p.mediaIds || '').indexOf(id) !== -1; })
    .map(function (p) { return p.title || 'Untitled post'; });
  if (usedBy.length && !force) return { ok: false, usedBy: usedBy };
  try { Db.drive.trash(item.driveFileId); } catch (e) { /* already gone */ }
  Db.withLock(function () { Db.removeWhere('Media', 'id', id); });
  Db.log('info', 'media', 'Moved “' + item.fileName + '” to the Drive trash');
  return { ok: true };
}

/** Apply the same change to many items: { folder?, addTags?: [], removeTags?: [] }. */
function bulkUpdateMedia(ids, change) {
  Db.ensure();
  var folders = change.folder ? Db.folders().mediaFolders : null;
  if (change.folder && !folders[change.folder]) throw new Error('Unknown folder');
  var updated = [];
  ids.forEach(function (id) {
    var cur = Db.get('Media', id);
    if (!cur) return;
    var patch = {};
    if (change.folder && cur.folder !== change.folder) {
      Db.drive.move(cur.driveFileId, folders[change.folder]);
      patch.folder = change.folder; patch.driveFolderId = folders[change.folder];
    }
    if (change.addTags || change.removeTags) {
      var tags = [];
      try { tags = JSON.parse(cur.tags || '[]'); } catch (e) { tags = []; }
      (change.addTags || []).forEach(function (t) { t = String(t).trim().toLowerCase(); if (t && tags.indexOf(t) === -1) tags.push(t); });
      var rm = (change.removeTags || []).map(function (t) { return String(t).trim().toLowerCase(); });
      patch.tags = tags.filter(function (t) { return rm.indexOf(t) === -1; }).slice(0, 30);
    }
    var saved = Object.keys(patch).length ? Db.withLock(function () { return Db.update('Media', id, patch); }) : cur;
    updated.push(parseMediaRow_(saved));
  });
  Db.log('info', 'media', 'Updated ' + updated.length + ' media items' + (change.folder ? ' (moved to ' + change.folder + ')' : ''));
  return updated;
}

/** Move many items to the Drive trash. Items used in posts are skipped unless force is true. */
function bulkDeleteMedia(ids, force) {
  Db.ensure();
  var posts = Db.all('Posts');
  var inUse = [], deleted = [];
  ids.forEach(function (id) {
    var item = Db.get('Media', id);
    if (!item) { deleted.push(id); return; }
    var usedBy = posts.filter(function (p) { return String(p.mediaIds || '').indexOf(id) !== -1; }).map(function (p) { return p.title || 'Untitled post'; });
    if (usedBy.length && !force) { inUse.push({ id: id, fileName: item.fileName, usedBy: usedBy }); return; }
    try { Db.drive.trash(item.driveFileId); } catch (e) { /* already gone */ }
    Db.withLock(function () { Db.removeWhere('Media', 'id', id); });
    deleted.push(id);
  });
  if (deleted.length) Db.log('info', 'media', 'Moved ' + deleted.length + ' media items to the Drive trash');
  return { deleted: deleted, inUse: inUse };
}

/**
 * Crafty Rose Social Studio — posts, drafts and the publishing queue.
 *
 * A post is stored once (Posts) with one row per platform (PostTargets), so each
 * platform keeps its own caption, settings and publishing status.
 *
 * Scheduled posts are sent by the publisher (Publisher.gs) when they're due.
 * Platforms that aren't connected yet are flagged "needs attention" at that time.
 */

var POST_STATUSES = ['draft', 'scheduled', 'publishing', 'published', 'failed', 'attention', 'partial'];
var PLATFORM_IDS = ['instagram', 'facebook', 'tiktok', 'youtube', 'pinterest'];

function iso_(v) { return v instanceof Date ? v.toISOString() : String(v || ''); }
function json_(v, fallback) {
  if (v === '' || v === null || v === undefined) return fallback;
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return fallback; }
}

function parsePost_(r) {
  return {
    id: r.id, title: r.title, postType: r.postType, status: r.status,
    baseCaption: r.baseCaption, baseHashtags: r.baseHashtags, link: r.link,
    mediaIds: json_(r.mediaIds, []), platforms: json_(r.platforms, []),
    scheduledAt: iso_(r.scheduledAt), inQueue: r.inQueue === true || r.inQueue === 'TRUE',
    notes: r.notes, createdAt: iso_(r.createdAt), updatedAt: iso_(r.updatedAt)
  };
}

function parseTarget_(r) {
  return {
    id: r.id, postId: r.postId, platform: r.platform, format: r.format,
    customize: json_(r.options, {}).customize === true,
    caption: r.caption, hashtags: r.hashtags, title: r.title, description: r.description,
    destinationUrl: r.destinationUrl, coverMediaId: r.coverMediaId,
    mediaIds: json_(r.mediaIds, []), options: json_(r.options, {}), status: r.status,
    scheduledAt: iso_(r.scheduledAt), publishedAt: iso_(r.publishedAt),
    platformUrl: r.platformUrl, attempts: Number(r.attempts || 0), lastError: r.lastError
  };
}

/** Create or update a post and its per-platform versions. */
function savePost(input) {
  Db.ensure();
  if (!input) throw new Error('Nothing to save');
  var status = POST_STATUSES.indexOf(input.status) !== -1 ? input.status : 'draft';
  var platforms = (input.platforms || []).filter(function (p) { return PLATFORM_IDS.indexOf(p) !== -1; });
  if (input.publishNow) { status = 'scheduled'; input.scheduledAt = new Date().toISOString(); input.inQueue = false; }
  if (status === 'scheduled') {
    if (!platforms.length) throw new Error('Choose at least one platform before scheduling.');
    var when = new Date(input.scheduledAt);
    if (isNaN(when.getTime())) throw new Error('Choose a date and time to schedule this post.');
    if (!input.publishNow && when.getTime() < Date.now() + 5 * 60000) throw new Error('Pick a time at least 5 minutes from now.');
  }
  if (input.id) {
    var existing = Db.get('Posts', input.id);
    if (existing && ['publishing', 'published', 'partial'].indexOf(existing.status) !== -1) {
      throw new Error('This post has already been (partly) published, so it can’t be edited. Duplicate it to make a new version.');
    }
  }

  var postRow = {
    title: String(input.title || '').slice(0, 200) || 'Untitled post',
    postType: input.postType || 'photo',
    status: status,
    baseCaption: String(input.baseCaption || '').slice(0, 70000),
    baseHashtags: String(input.baseHashtags || '').slice(0, 5000),
    link: String(input.link || '').slice(0, 2048),
    mediaIds: input.mediaIds || [],
    platforms: platforms,
    scheduledAt: input.scheduledAt || '',
    timeZone: APP.timeZone,
    inQueue: !!input.inQueue,
    notes: String(input.notes || '').slice(0, 5000)
  };

  return Db.withLock(function () {
    var saved;
    if (input.id && Db.get('Posts', input.id)) {
      saved = Db.update('Posts', input.id, postRow);
      Db.removeWhere('PostTargets', 'postId', input.id);
    } else {
      saved = Db.insert('Posts', postRow);
    }
    var targets = input.targets || {};
    platforms.forEach(function (p) {
      var t = targets[p] || {};
      var options = t.options || {};
      options.customize = !!t.customize;
      Db.insert('PostTargets', {
        postId: saved.id, platform: p, format: t.format || '',
        caption: t.customize ? String(t.caption || '') : '',
        hashtags: t.customize ? String(t.hashtags || '') : '',
        title: String(t.title || '').slice(0, 200),
        description: String(t.description || '').slice(0, 6000),
        destinationUrl: String(t.destinationUrl || '').slice(0, 2048),
        coverMediaId: t.coverMediaId || '',
        mediaIds: t.mediaIds || [],
        options: options,
        status: status === 'scheduled' ? 'scheduled' : 'draft',
        scheduledAt: postRow.scheduledAt, attempts: 0
      });
    });
    Db.log(status === 'scheduled' ? 'info' : 'info', 'post',
      (status === 'scheduled' ? 'Scheduled “' : 'Saved draft “') + postRow.title + '”', { postId: saved.id });
    return getPost(saved.id);
  });
}

/** One post with its platform versions. */
function getPost(id) {
  var row = Db.get('Posts', id);
  if (!row) throw new Error('Post not found');
  var post = parsePost_(row);
  var targets = {};
  Db.all('PostTargets').filter(function (t) { return t.postId === id; }).forEach(function (t) {
    var pt = parseTarget_(t);
    targets[pt.platform] = pt;
  });
  post.targets = targets;
  return post;
}

/** Posts for the lists (Drafts, Scheduled, dashboard), with a cover thumbnail. */
function listPosts(filter) {
  filter = filter || {};
  var media = {};
  Db.all('Media').forEach(function (m) { media[m.id] = { thumbData: m.thumbData, kind: m.kind, durationSec: m.durationSec }; });
  var targets = {};
  Db.all('PostTargets').forEach(function (t) {
    (targets[t.postId] = targets[t.postId] || []).push({ id: t.id, platform: t.platform, status: t.status, format: t.format, lastError: t.lastError,
      platformUrl: t.platformUrl || '', publishedAt: iso_(t.publishedAt) });
  });
  return Db.all('Posts').map(parsePost_).filter(function (p) {
    return !filter.status || filter.status.indexOf(p.status) !== -1;
  }).map(function (p) {
    var first = media[p.mediaIds[0]] || null;
    p.cover = first ? { thumbData: first.thumbData, kind: first.kind, durationSec: Number(first.durationSec) || null } : null;
    p.mediaCount = p.mediaIds.length;
    p.targets = targets[p.id] || [];
    return p;
  }).sort(function (a, b) {
    var recent = function (p) { return ['draft', 'published', 'partial', 'failed'].indexOf(p.status) !== -1; };
    var ka = a.status === 'draft' ? a.updatedAt : a.scheduledAt;
    var kb = b.status === 'draft' ? b.updatedAt : b.scheduledAt;
    return recent(a) ? (ka < kb ? 1 : -1) : (ka > kb ? 1 : -1);
  });
}

function deletePost(id) {
  Db.ensure();
  var row = Db.get('Posts', id);
  Db.withLock(function () {
    Db.removeWhere('PostTargets', 'postId', id);
    Db.removeWhere('Posts', 'id', id);
  });
  if (row) Db.log('info', 'post', 'Deleted “' + row.title + '”');
  return { ok: true };
}

function duplicatePost(id) {
  var p = getPost(id);
  var copy = {
    title: p.title + ' (copy)', postType: p.postType, status: 'draft',
    baseCaption: p.baseCaption, baseHashtags: p.baseHashtags, link: p.link,
    mediaIds: p.mediaIds, platforms: p.platforms, scheduledAt: '', notes: p.notes, targets: {}
  };
  Object.keys(p.targets).forEach(function (k) {
    var t = p.targets[k];
    copy.targets[k] = { customize: t.customize, caption: t.caption, hashtags: t.hashtags, title: t.title,
      description: t.description, destinationUrl: t.destinationUrl, format: t.format,
      coverMediaId: t.coverMediaId, mediaIds: t.mediaIds, options: t.options };
  });
  return savePost(copy);
}

function moveToDrafts(id) {
  Db.ensure();
  Db.withLock(function () {
    Db.update('Posts', id, { status: 'draft', inQueue: false });
    Db.all('PostTargets').filter(function (t) { return t.postId === id; }).forEach(function (t) {
      Db.update('PostTargets', t.id, { status: 'draft' });
    });
  });
  return getPost(id);
}

/** Read a value from the Settings tab. */
function getSetting_(key, fallback) {
  var rows = Db.all('Settings').filter(function (r) { return r.key === key; });
  return rows.length ? rows[0].value : fallback;
}

/**
 * Next free publishing-queue slot (Atlantic Time). Slots come from Settings › queueSlots,
 * e.g. Tue 10:00, Thu 18:30, Sat 10:00. A slot is "taken" if a scheduled post is within an hour of it.
 */
function nextQueueSlot() {
  Db.ensure();
  var slots = json_(getSetting_('queueSlots', DEFAULT_SETTINGS.queueSlots), []);
  if (!slots.length) return null;
  var taken = Db.all('Posts').filter(function (p) { return p.status === 'scheduled'; })
    .map(function (p) { return new Date(p.scheduledAt).getTime(); });
  var tz = APP.timeZone;
  var now = Date.now() + 30 * 60000;
  for (var d = 0; d < 60; d++) {
    var day = new Date(Date.now() + d * 86400000);
    var ymd = Utilities.formatDate(day, tz, 'yyyy-MM-dd');
    var dow = Number(Utilities.formatDate(day, tz, 'u')) % 7; // 0 = Sunday
    for (var i = 0; i < slots.length; i++) {
      if (Number(slots[i].day) !== dow) continue;
      var at = Utilities.parseDate(ymd + ' ' + slots[i].time, tz, 'yyyy-MM-dd HH:mm').getTime();
      if (at < now) continue;
      var clash = taken.some(function (t) { return Math.abs(t - at) < 3600000; });
      if (!clash) return { iso: new Date(at).toISOString() };
    }
  }
  return null;
}

/**
 * Move a post to a new date/time (calendar drag & drop, "change time").
 * Drafts can be given a planned date; scheduled posts must stay in the future.
 */
function reschedulePost(id, iso) {
  Db.ensure();
  var row = Db.get('Posts', id);
  if (!row) throw new Error('Post not found');
  if (['published', 'publishing'].indexOf(row.status) !== -1) throw new Error('Published posts can’t be moved.');
  var when = new Date(iso);
  if (isNaN(when.getTime())) throw new Error('That date isn’t valid.');
  if (row.status === 'scheduled' && when.getTime() < Date.now() + 5 * 60000) throw new Error('Scheduled posts need a time at least 5 minutes from now.');
  Db.withLock(function () {
    Db.update('Posts', id, { scheduledAt: when.toISOString(), inQueue: false });
    Db.all('PostTargets').filter(function (t) { return t.postId === id; }).forEach(function (t) {
      Db.update('PostTargets', t.id, { scheduledAt: when.toISOString() });
    });
  });
  Db.log('info', 'post', 'Moved “' + row.title + '” to ' + Utilities.formatDate(when, APP.timeZone, 'EEE MMM d, h:mm a'), { postId: id });
  return listPosts().filter(function (p) { return p.id === id; })[0];
}

/**
 * Crafty Rose Social Studio — the publisher (Phase 3).
 *
 * A time-driven trigger runs publishDue() every 5 minutes. It picks up platform
 * versions (PostTargets) that are due, and moves each one through small steps:
 *   upload → processing → publish → done
 * The progress is saved in PostTargets.pubState, so a long video can continue on
 * the next run. Each platform succeeds or fails on its own (retry one platform only).
 *
 * Your original media files are never changed. For Instagram photos, Meta has to
 * download the image from a public link, so the studio shares the photo (or a
 * temporary JPEG copy) by link for the few seconds it takes, then removes the link.
 */

var PUB = {
  chunk: 40 * 1024 * 1024,       // bytes per upload request (Apps Script allows 50 MB)
  runBudgetMs: 270 * 1000,       // stay well under the 6-minute execution limit
  maxAttempts: 3,
  defaultTagModes: { instagram: 'first5', tiktok: 'first5', facebook: 'first2', youtube: 'first3', pinterest: 'none' }
};

/* ------------------------------------------------------------------ */
/* Trigger management                                                  */
/* ------------------------------------------------------------------ */

function ensurePublisherTrigger_() {
  var has = ScriptApp.getProjectTriggers().some(function (t) { return t.getHandlerFunction() === 'publishDue'; });
  if (!has) ScriptApp.newTrigger('publishDue').timeBased().everyMinutes(5).create();
  return true;
}

function publisherStatus_() {
  var on = false;
  try { on = ScriptApp.getProjectTriggers().some(function (t) { return t.getHandlerFunction() === 'publishDue'; }); } catch (e) { on = false; }
  return { running: on, lastRun: Secrets.get('PUB_LAST_RUN'), lastSummary: Secrets.get('PUB_LAST_SUMMARY') };
}

/** Called from Social Accounts › "Turn on automatic publishing" if the trigger is missing. */
function enablePublisher() { ensurePublisherTrigger_(); return publisherStatus_(); }

/* ------------------------------------------------------------------ */
/* Entry points                                                        */
/* ------------------------------------------------------------------ */

/** Trigger: publish everything that is due. */
function publishDue() {
  var lock = LockService.getUserLock();
  if (!lock.tryLock(1000)) return;
  try {
    Db.ensure();
    var deadline = Date.now() + PUB.runBudgetMs;
    var now = Date.now();
    var due = Db.all('PostTargets').filter(function (t) {
      if (t.status === 'publishing') return true;
      if (t.status !== 'scheduled') return false;
      var at = new Date(t.scheduledAt).getTime();
      return !isNaN(at) && at <= now;
    });
    var done = 0, failed = 0;
    due.forEach(function (t) {
      if (Date.now() > deadline - 20000) return;
      var r = processTarget_(t.id, deadline);
      if (r === 'published') done++; else if (r === 'failed' || r === 'attention') failed++;
    });
    Secrets.set('PUB_LAST_RUN', new Date().toISOString());
    Secrets.set('PUB_LAST_SUMMARY', due.length ? (done + ' published, ' + failed + ' need attention, ' + (due.length - done - failed) + ' in progress') : 'Nothing due');
  } finally { lock.releaseLock(); }
}

/** "Publish now" from the post creator: publish one post's platforms immediately. */
function publishPost(postId) {
  Db.ensure();
  var post = Db.get('Posts', postId);
  if (!post) throw new Error('Post not found');
  var lock = LockService.getUserLock();
  lock.waitLock(30000);
  try {
    var deadline = Date.now() + PUB.runBudgetMs;
    Db.all('PostTargets').filter(function (t) { return t.postId === postId && (t.status === 'scheduled' || t.status === 'publishing'); })
      .forEach(function (t) { if (Date.now() < deadline - 20000) processTarget_(t.id, deadline); });
  } finally { lock.releaseLock(); }
  try { ensurePublisherTrigger_(); } catch (e) { /* trigger permission not granted yet */ }
  return getPost(postId);
}

/** Retry one platform (e.g. Instagram failed, Facebook worked). */
function retryTarget(targetId) {
  Db.ensure();
  var t = Db.get('PostTargets', targetId);
  if (!t) throw new Error('That platform version wasn’t found.');
  if (t.status === 'published') throw new Error('This one is already published.');
  Db.withLock(function () {
    Db.update('PostTargets', targetId, { status: 'scheduled', scheduledAt: new Date().toISOString(), pubState: '', attempts: 0, lastError: '' });
    Db.update('Posts', t.postId, { status: 'publishing' });
  });
  Db.log('info', 'publish', 'Retrying ' + t.platform, { postId: t.postId, targetId: targetId, platform: t.platform });
  return publishPost(t.postId);
}

/** Mark a platform as posted by hand (for platforms that aren't connected yet). */
function markTargetPostedManually(targetId, url) {
  var t = Db.get('PostTargets', targetId);
  if (!t) throw new Error('Not found');
  Db.withLock(function () {
    Db.update('PostTargets', targetId, { status: 'published', publishedAt: new Date().toISOString(), platformUrl: String(url || ''), lastError: '', pubState: '' });
  });
  updatePostStatus_(t.postId);
  return getPost(t.postId);
}

/** Caption exactly as it would be posted on one platform (for posting by hand). */
function getTargetCaption(targetId) {
  var t = Db.get('PostTargets', targetId);
  if (!t) throw new Error('Not found');
  var post = Db.get('Posts', t.postId);
  var opts = json_(t.options, {}) || {};
  var caption = opts.customize ?
    (t.platform === 'youtube' ? String(t.description || '') : joinCaption_(t.caption, normTags_(t.hashtags))) :
    joinCaption_(post.baseCaption, applyTagMode_(post.baseHashtags, opts.hashtagMode || PUB.defaultTagModes[t.platform]));
  return { platform: t.platform, caption: caption, title: String(t.title || ''), link: String(post.link || '') };
}

/* ------------------------------------------------------------------ */
/* One platform version                                                */
/* ------------------------------------------------------------------ */

function processTarget_(targetId, deadline) {
  var t = Db.get('PostTargets', targetId);
  if (!t) return 'missing';
  var post = Db.get('Posts', t.postId);
  if (!post) return 'missing';
  var pf = t.platform;
  var connected = connectedPlatforms_();

  if (!connected[pf]) {
    var name = { instagram: 'Instagram', facebook: 'Facebook', tiktok: 'TikTok', youtube: 'YouTube', pinterest: 'Pinterest' }[pf] || pf;
    saveTarget_(t, { status: 'attention', lastError: name + ' isn’t connected yet. Post it by hand, then tick “Posted manually” — or connect it in Social Accounts and retry.', lastAttemptAt: new Date().toISOString() });
    Db.log('warning', 'publish', name + ' needs attention for “' + post.title + '” (not connected)', { postId: post.id, targetId: t.id, platform: pf });
    updatePostStatus_(post.id);
    return 'attention';
  }

  var state = json_(t.pubState, {}) || {};
  var starting = t.status === 'scheduled' && !state.stage;
  var patch = { status: 'publishing', lastAttemptAt: new Date().toISOString() };
  if (starting) patch.attempts = Number(t.attempts || 0) + 1;
  saveTarget_(t, patch);
  if (starting) { Db.update('Posts', post.id, { status: 'publishing' }); }

  var ctx = buildContext_(t, post);
  try {
    var r = pf === 'instagram' ? igStep_(ctx, state, deadline) : fbStep_(ctx, state, deadline);
    if (r && r.done) {
      cleanupShares_(state);
      saveTarget_(t, { status: 'published', publishedAt: new Date().toISOString(), platformPostId: r.id || '', platformUrl: r.url || '', lastError: '', pubState: '' });
      Db.log('success', 'publish', 'Published “' + post.title + '” to ' + ctx.name, { postId: post.id, targetId: t.id, platform: pf, details: r.url || '' });
      updatePostStatus_(post.id);
      return 'published';
    }
    saveTarget_(t, { pubState: JSON.stringify(state) });
    return 'waiting';
  } catch (e) {
    var attempts = Number(starting ? patch.attempts : t.attempts || 1);
    var retry = e.transient && attempts < PUB.maxAttempts;
    if (!retry) cleanupShares_(state);
    saveTarget_(t, retry ?
      { status: 'scheduled', pubState: '', lastError: 'Will retry: ' + e.message, scheduledAt: new Date(Date.now() + 10 * 60000).toISOString() } :
      { status: 'failed', pubState: '', lastError: e.message });
    Db.log(retry ? 'warning' : 'error', 'publish', (retry ? 'Will retry ' : 'Couldn’t publish ') + '“' + post.title + '” on ' + ctx.name + ': ' + e.message,
      { postId: post.id, targetId: t.id, platform: pf });
    if (!retry) updatePostStatus_(post.id);
    return retry ? 'retry' : 'failed';
  }
}

function saveTarget_(t, patch) {
  Db.withLock(function () { Db.update('PostTargets', t.id, patch); });
  Object.keys(patch).forEach(function (k) { t[k] = patch[k]; });
}

/** Roll the platform results up into the post's own status. */
function updatePostStatus_(postId) {
  var ts = Db.all('PostTargets').filter(function (t) { return t.postId === postId; });
  if (!ts.length) return;
  var st = ts.map(function (t) { return t.status; });
  var count = function (s) { return st.filter(function (x) { return x === s; }).length; };
  var pub = count('published'), bad = count('failed') + count('attention');
  var status = pub === ts.length ? 'published' :
    (count('publishing') || count('scheduled')) ? (pub || bad || count('publishing') ? 'publishing' : 'scheduled') :
    pub ? 'partial' : 'failed';
  Db.withLock(function () { Db.update('Posts', postId, { status: status }); });
}

/* ------------------------------------------------------------------ */
/* Caption + media for a platform version (mirrors the post creator)   */
/* ------------------------------------------------------------------ */

function normTags_(s) {
  return String(s || '').split(/[\s,]+/).map(function (t) { return t.replace(/^#+/, '').replace(/[^\p{L}\p{N}_]/gu, ''); })
    .filter(Boolean).map(function (t) { return '#' + t; });
}
function applyTagMode_(tags, mode) {
  var list = normTags_(tags);
  if (mode === 'none') return [];
  var m = /^first(\d+)$/.exec(mode || '');
  return m ? list.slice(0, Number(m[1])) : list;
}
function joinCaption_(text, tags) {
  text = String(text || '').trim(); tags = tags.join(' ');
  return text && tags ? text + '\n\n' + tags : text || tags;
}

function buildContext_(t, post) {
  var opts = json_(t.options, {}) || {};
  var pf = t.platform;
  var caption = opts.customize ?
    (pf === 'youtube' ? String(t.description || '') : joinCaption_(t.caption, normTags_(t.hashtags))) :
    joinCaption_(post.baseCaption, applyTagMode_(post.baseHashtags, opts.hashtagMode || PUB.defaultTagModes[pf]));
  var ids = json_(t.mediaIds, []);
  if (!ids || !ids.length) ids = json_(post.mediaIds, []);
  var byId = {};
  Db.all('Media').forEach(function (m) { byId[m.id] = m; });
  var media = ids.map(function (id) { return byId[id]; }).filter(Boolean).map(function (m) {
    return { id: m.id, fileId: m.driveFileId, name: m.fileName, kind: m.kind, mime: m.mimeType, size: Number(m.sizeBytes) || 0,
      width: Number(m.width) || 0, height: Number(m.height) || 0, duration: Number(m.durationSec) || 0, imageFormat: String(m.imageFormat || '') };
  });
  var creds = metaCreds_();
  var fmt = t.format || autoFormat_(pf, media);
  return {
    platform: pf, name: pf === 'instagram' ? 'Instagram' : 'Facebook', format: fmt, caption: caption, link: String(post.link || ''),
    title: String(t.title || ''), options: opts, media: media, creds: creds, postTitle: post.title
  };
}

function autoFormat_(pf, media) {
  var vids = media.filter(function (m) { return m.kind === 'video'; });
  if (pf === 'instagram') return media.length > 1 ? 'carousel' : vids.length ? 'reel' : 'feed';
  if (pf === 'facebook') {
    if (!vids.length) return 'post';
    var v = vids[0];
    return v.height > v.width && v.duration >= 3 && v.duration <= 90 ? 'reel' : 'video';
  }
  return '';
}

/* ------------------------------------------------------------------ */
/* Instagram                                                           */
/* ------------------------------------------------------------------ */

function igStep_(ctx, state, deadline) {
  var c = ctx.creds, tok = c.pageToken;
  if (!c.igId) throw new Error('No Instagram account is linked to your Facebook Page.');
  if (!ctx.media.length) throw new Error('Instagram posts need a photo or video.');

  if (!state.stage) {
    state.containers = [];
    state.shares = [];
    var isCarousel = ctx.format === 'carousel' && ctx.media.length > 1;
    ctx.media.slice(0, isCarousel ? 10 : 1).forEach(function (m) {
      var p = { access_token: tok };
      if (isCarousel) p.is_carousel_item = 'true';
      if (m.kind === 'video') {
        p.media_type = isCarousel ? 'VIDEO' : 'REELS';
        p.upload_type = 'resumable';
        if (!isCarousel) {
          p.caption = ctx.caption;
          p.share_to_feed = ctx.options.shareToFeed === false ? 'false' : 'true';
          if (Number(ctx.options.coverOffsetSec) > 0) p.thumb_offset = String(Math.round(Number(ctx.options.coverOffsetSec) * 1000));
        }
        var v = metaApi_('post', c.igId + '/media', p);
        state.containers.push({ id: v.id, uri: v.uri, fileId: m.fileId, size: m.size || driveSize_(m.fileId), offset: 0, video: true });
      } else {
        p.image_url = publicImageUrl_(m, state);
        if (!isCarousel) { p.caption = ctx.caption; if (ctx.options.altText) p.alt_text = String(ctx.options.altText).slice(0, 1000); }
        var im = metaApi_('post', c.igId + '/media', p);
        state.containers.push({ id: im.id, done: true });
      }
    });
    state.carousel = isCarousel;
    state.stage = 'upload';
  }

  if (state.stage === 'upload') {
    for (var i = 0; i < state.containers.length; i++) {
      var k = state.containers[i];
      if (!k.video || k.offset >= k.size) continue;
      k.offset = ruploadFile_(k.uri, k.fileId, k.size, k.offset, { Authorization: 'OAuth ' + tok }, deadline);
      if (k.offset < k.size) return { wait: true };
    }
    state.stage = 'processing';
  }

  if (state.stage === 'processing') {
    var ready = waitContainers_(state.containers.map(function (k) { return k.id; }).concat(state.parent ? [state.parent] : []), tok, deadline);
    if (!ready) return { wait: true };
    if (state.carousel && !state.parent) {
      var parent = metaApi_('post', c.igId + '/media', { media_type: 'CAROUSEL', children: state.containers.map(function (k) { return k.id; }).join(','), caption: ctx.caption, access_token: tok });
      state.parent = parent.id;
      if (!waitContainers_([state.parent], tok, deadline)) return { wait: true };
    }
    state.stage = 'publish';
  }

  if (state.stage === 'publish') {
    var creation = state.parent || state.containers[0].id;
    var pub = metaApi_('post', c.igId + '/media_publish', { creation_id: creation, access_token: tok });
    var info = {};
    try { info = metaApi_('get', pub.id, { fields: 'permalink', access_token: tok }); } catch (e) { info = {}; }
    return { done: true, id: pub.id, url: info.permalink || 'https://www.instagram.com/' };
  }
  return { wait: true };
}

/** Poll Instagram containers until FINISHED (up to ~2 minutes in this run). */
function waitContainers_(ids, tok, deadline) {
  var until = Math.min(deadline - 15000, Date.now() + 120000);
  while (true) {
    var pending = false;
    for (var i = 0; i < ids.length; i++) {
      var s = metaApi_('get', ids[i], { fields: 'status_code,status', access_token: tok });
      if (s.status_code === 'ERROR' || s.status_code === 'EXPIRED') throw new Error('Instagram couldn’t process the media (' + (s.status || s.status_code) + ').');
      if (s.status_code !== 'FINISHED' && s.status_code !== 'PUBLISHED') pending = true;
    }
    if (!pending) return true;
    if (Date.now() + 10000 > until) return false;
    Utilities.sleep(8000);
  }
}

/* ------------------------------------------------------------------ */
/* Facebook Page                                                       */
/* ------------------------------------------------------------------ */

function fbStep_(ctx, state, deadline) {
  var c = ctx.creds, tok = c.pageToken;
  var images = ctx.media.filter(function (m) { return m.kind !== 'video'; });
  var video = ctx.media.filter(function (m) { return m.kind === 'video'; })[0];

  if (ctx.format === 'reel' && video) return fbReel_(ctx, state, video, deadline);
  if (video && (ctx.format === 'video' || !images.length)) return fbVideo_(ctx, state, video, deadline);

  var message = ctx.caption;
  if (images.length) {
    if (ctx.link && message.indexOf(ctx.link) === -1) message = (message ? message + '\n\n' : '') + ctx.link;
    if (images.length === 1) {
      var one = metaApi_('post', c.pageId + '/photos', { source: driveBlob_(images[0]), message: message, access_token: tok });
      return { done: true, id: one.post_id || one.id, url: fbPermalink_(one.post_id || one.id, tok) };
    }
    var params = { message: message, access_token: tok };
    images.slice(0, 10).forEach(function (m, i) {
      var ph = metaApi_('post', c.pageId + '/photos', { source: driveBlob_(m), published: 'false', access_token: tok });
      params['attached_media[' + i + ']'] = JSON.stringify({ media_fbid: ph.id });
    });
    var multi = metaApi_('post', c.pageId + '/feed', params);
    return { done: true, id: multi.id, url: fbPermalink_(multi.id, tok) };
  }
  if (!message && !ctx.link) throw new Error('Add text, a link or media.');
  var feed = metaApi_('post', c.pageId + '/feed', { message: message, link: ctx.link, access_token: tok });
  return { done: true, id: feed.id, url: fbPermalink_(feed.id, tok) };
}

function fbReel_(ctx, state, video, deadline) {
  var c = ctx.creds, tok = c.pageToken;
  if (!state.stage) {
    var start = metaApi_('post', c.pageId + '/video_reels', { upload_phase: 'start', access_token: tok });
    state.videoId = start.video_id;
    state.uploadUrl = start.upload_url || ('https://rupload.facebook.com/video-upload/' + META.version + '/' + start.video_id);
    state.size = video.size || driveSize_(video.fileId);
    state.offset = 0;
    state.fileId = video.fileId;
    state.stage = 'upload';
  }
  if (state.stage === 'upload') {
    state.offset = ruploadFile_(state.uploadUrl, state.fileId, state.size, state.offset, { Authorization: 'OAuth ' + tok }, deadline);
    if (state.offset < state.size) return { wait: true };
    state.stage = 'finish';
  }
  if (state.stage === 'finish') {
    metaApi_('post', c.pageId + '/video_reels', { upload_phase: 'finish', video_id: state.videoId, video_state: 'PUBLISHED', description: ctx.caption, access_token: tok });
    state.stage = 'processing';
  }
  if (state.stage === 'processing') {
    var until = Math.min(deadline - 15000, Date.now() + 90000);
    while (true) {
      var s = metaApi_('get', state.videoId, { fields: 'status,permalink_url', access_token: tok });
      var st = s.status || {};
      if (st.video_status === 'error' || st.video_status === 'upload_failed' || st.video_status === 'expired' ||
          (st.processing_phase && st.processing_phase.status === 'error') || (st.publishing_phase && st.publishing_phase.status === 'error')) {
        var why = (st.processing_phase && st.processing_phase.errors && st.processing_phase.errors[0] && st.processing_phase.errors[0].message) ||
          (st.publishing_phase && st.publishing_phase.errors && st.publishing_phase.errors[0] && st.publishing_phase.errors[0].message) || st.video_status;
        throw new Error('Facebook couldn’t process the Reel: ' + why);
      }
      var published = st.publishing_phase && st.publishing_phase.status === 'complete';
      if (published || st.video_status === 'ready') return { done: true, id: state.videoId, url: absFb_(s.permalink_url) || 'https://www.facebook.com/reel/' + state.videoId };
      if (Date.now() + 10000 > until) return { wait: true };
      Utilities.sleep(8000);
    }
  }
  return { wait: true };
}

function fbVideo_(ctx, state, video, deadline) {
  var c = ctx.creds;
  if (!c.userToken) throw new Error('Reconnect Instagram & Facebook (the video upload permission needs a fresh login).');
  if (!state.stage) {
    var sess = metaApi_('post', c.appId + '/uploads', {
      file_name: video.name || 'video.mp4', file_length: String(video.size || driveSize_(video.fileId)),
      file_type: video.mime || 'video/mp4', access_token: c.userToken
    });
    state.session = sess.id;
    state.size = video.size || driveSize_(video.fileId);
    state.offset = 0;
    state.fileId = video.fileId;
    state.stage = 'upload';
  }
  if (state.stage === 'upload') {
    while (state.offset < state.size) {
      if (Date.now() > deadline - 30000) return { wait: true };
      var end = Math.min(state.size, state.offset + PUB.chunk) - 1;
      var res = metaApi_('post', META.graph + state.session, {}, {
        headers: { Authorization: 'OAuth ' + c.userToken, file_offset: String(state.offset) },
        body: driveBytes_(state.fileId, state.offset, end).getBytes(), contentType: 'application/octet-stream'
      });
      state.offset = end + 1;
      if (res.h) state.handle = res.h;
    }
    if (!state.handle) throw new Error('Facebook didn’t confirm the video upload. Please retry.');
    state.stage = 'publish';
  }
  if (state.stage === 'publish') {
    var v = metaApi_('post', 'https://graph-video.facebook.com/' + META.version + '/' + c.pageId + '/videos', {
      access_token: c.pageToken, description: ctx.caption, title: ctx.title || '', fbuploader_video_file_chunk: state.handle
    });
    return { done: true, id: v.id, url: fbPermalink_(v.id, c.pageToken) || 'https://www.facebook.com/' + v.id };
  }
  return { wait: true };
}

function fbPermalink_(id, tok) {
  try { return absFb_(metaApi_('get', id, { fields: 'permalink_url', access_token: tok }).permalink_url); } catch (e) { return 'https://www.facebook.com/' + id; }
}
function absFb_(u) { return !u ? '' : /^https?:/.test(u) ? u : 'https://www.facebook.com' + u; }

/* ------------------------------------------------------------------ */
/* Drive helpers (read-only access to your original files)             */
/* ------------------------------------------------------------------ */

function driveSize_(fileId) { return Number(Db.drive.req('get', 'files/' + fileId, null, { fields: 'size' }).size) || 0; }

function driveBytes_(fileId, start, end) {
  var res = UrlFetchApp.fetch('https://www.googleapis.com/drive/v3/files/' + fileId + '?alt=media', {
    headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken(), Range: 'bytes=' + start + '-' + end }, muteHttpExceptions: true
  });
  if (res.getResponseCode() >= 300) throw new Error('Couldn’t read the file from Drive (' + res.getResponseCode() + '). Is it still in your Media Library?');
  return res.getBlob();
}

function driveBlob_(m) {
  var size = m.size || driveSize_(m.fileId);
  if (size > PUB.chunk) throw new Error('“' + m.name + '” is too large to send in one piece (' + Math.round(size / 1048576) + ' MB).');
  var res = UrlFetchApp.fetch('https://www.googleapis.com/drive/v3/files/' + m.fileId + '?alt=media', {
    headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }, muteHttpExceptions: true
  });
  if (res.getResponseCode() >= 300) throw new Error('Couldn’t read “' + m.name + '” from Drive.');
  return res.getBlob().setName(m.name || 'image.jpg');
}

/** Send a Drive file to Meta's upload server in pieces. Returns the new offset. */
function ruploadFile_(url, fileId, size, offset, headers, deadline) {
  while (offset < size) {
    if (Date.now() > deadline - 30000) return offset;
    var end = Math.min(size, offset + PUB.chunk) - 1;
    var h = { offset: String(offset), file_size: String(size) };
    Object.keys(headers).forEach(function (k) { h[k] = headers[k]; });
    var res = UrlFetchApp.fetch(url, { method: 'post', headers: h, payload: driveBytes_(fileId, offset, end).getBytes(), contentType: 'application/octet-stream', muteHttpExceptions: true });
    var text = res.getContentText();
    if (res.getResponseCode() >= 300) {
      var msg = text; try { var j = JSON.parse(text); msg = (j.debug_info && j.debug_info.message) || (j.error && j.error.message) || text; } catch (e) { /* keep text */ }
      var err = new Error('Video upload failed: ' + String(msg).slice(0, 200)); err.transient = res.getResponseCode() >= 500; throw err;
    }
    offset = end + 1;
  }
  return offset;
}

/**
 * Instagram downloads photos from a public link. Share the photo (or a temporary
 * JPEG copy for PNG/WebP/etc.) by link, check the link works, and remember it so
 * it can be un-shared as soon as Instagram has the photo.
 */
function publicImageUrl_(m, state) {
  state.shares = state.shares || [];
  var fileId = m.fileId, temp = false;
  var isJpeg = /jpe?g/i.test(m.imageFormat) || /image\/jpe?g/i.test(m.mime);
  if (!isJpeg) {
    var blob = driveBlob_(m).getAs('image/jpeg');
    var folders = Db.folders();
    var meta = { name: '_temp-for-instagram-' + (m.name || 'photo').replace(/\.[^.]+$/, '') + '.jpg', parents: [folders.root] };
    var boundary = 'crs' + Date.now();
    var body = Utilities.newBlob('--' + boundary + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + JSON.stringify(meta) +
      '\r\n--' + boundary + '\r\nContent-Type: image/jpeg\r\n\r\n').getBytes().concat(blob.getBytes())
      .concat(Utilities.newBlob('\r\n--' + boundary + '--').getBytes());
    var up = UrlFetchApp.fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id', {
      method: 'post', contentType: 'multipart/related; boundary=' + boundary, payload: body,
      headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }, muteHttpExceptions: true
    });
    if (up.getResponseCode() >= 300) throw new Error('Couldn’t make a JPEG copy for Instagram.');
    fileId = JSON.parse(up.getContentText()).id;
    temp = true;
  }
  var perm = Db.drive.req('post', 'files/' + fileId + '/permissions', { role: 'reader', type: 'anyone' }, { fields: 'id' });
  state.shares.push({ fileId: fileId, permId: perm.id, temp: temp });
  var candidates = [
    'https://drive.usercontent.google.com/download?id=' + fileId + '&export=download',
    'https://lh3.googleusercontent.com/d/' + fileId + '=s0'
  ];
  for (var tries = 0; tries < 3; tries++) {
    for (var i = 0; i < candidates.length; i++) {
      try {
        var r = UrlFetchApp.fetch(candidates[i], { muteHttpExceptions: true, followRedirects: true });
        var type = String(r.getHeaders()['Content-Type'] || r.getHeaders()['content-type'] || '');
        if (r.getResponseCode() === 200 && /image\/|octet-stream/.test(type) && r.getBlob().getBytes().length > 1000) return candidates[i];
      } catch (e) { /* try next */ }
    }
    Utilities.sleep(2000);
  }
  throw new Error('Couldn’t create a temporary link for Instagram to fetch the photo. Please retry.');
}

function cleanupShares_(state) {
  (state && state.shares || []).forEach(function (s) {
    try {
      if (s.temp) Db.drive.trash(s.fileId);
      else Db.drive.req('delete', 'files/' + s.fileId + '/permissions/' + s.permId, null, null);
    } catch (e) { Db.log('warning', 'publish', 'Couldn’t remove a temporary share link — check Drive sharing for file ' + s.fileId); }
  });
  if (state) state.shares = [];
}

/**
 * SAMPLE DATA — for designing the dashboard in Phase 1 only.
 *
 * Nothing here comes from a real social media account. Every response carries
 * `isSample: true` and the interface shows a clear "Sample data" label.
 * This file is removed/bypassed once real accounts are connected (Phase 3–4).
 */

var SampleData = (function () {

  function seeded(seed) {
    var s = seed;
    return function () { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  }

  function isoInDays(days, hour, minute) {
    var d = new Date();
    d.setDate(d.getDate() + days);
    d.setHours(hour, minute || 0, 0, 0);
    return d.toISOString();
  }

  function engagementSeries(n) {
    var rnd = seeded(42);
    var out = [];
    var base = 140;
    for (var i = n - 1; i >= 0; i--) {
      var d = new Date(); d.setDate(d.getDate() - i);
      var weekend = (d.getDay() === 0 || d.getDay() === 6) ? 35 : 0;
      base += (rnd() - 0.42) * 14;
      out.push({ date: Utilities.formatDate(d, APP.timeZone, 'yyyy-MM-dd'),
                 value: Math.max(40, Math.round(base + weekend + rnd() * 40)) });
    }
    return out;
  }

  function dashboard() {
    var platforms = [
      { id: 'instagram', name: 'Instagram', handle: '@craftyrosegifts', followers: 1248, change: 3.4 },
      { id: 'tiktok',    name: 'TikTok',    handle: '@craftyrosegifts', followers: 2310, change: 6.1 },
      { id: 'facebook',  name: 'Facebook',  handle: 'Crafty Rose Gifts', followers: 862,  change: 1.2 },
      { id: 'pinterest', name: 'Pinterest', handle: '@craftyrosegifts', followers: 397,  change: 2.8 },
      { id: 'youtube',   name: 'YouTube',   handle: '@craftyrosegifts', followers: 184,  change: 4.5 }
    ];
    var series = engagementSeries(90);
    var last30 = series.slice(-30).reduce(function (a, p) { return a + p.value; }, 0);
    var prev30 = series.slice(-60, -30).reduce(function (a, p) { return a + p.value; }, 0);

    return {
      isSample: true,
      generatedAt: new Date().toISOString(),
      totals: {
        followers: platforms.reduce(function (a, p) { return a + p.followers; }, 0),
        followersChange: 3.9,
        scheduled: 7,
        publishedThisMonth: 11,
        engagement30: last30,
        engagementChange: Math.round(((last30 - prev30) / prev30) * 1000) / 10
      },
      platforms: platforms,
      engagementSeries: series,
      upcoming: [
        { id: 'p1', title: 'Teacher appreciation tumblers', caption: 'Personalized tumblers for the teachers who make every day brighter 🍎 Order by Friday for…', type: 'photo', category: 'drinkware', platforms: ['instagram', 'facebook'], scheduledAt: isoInDays(1, 10, 30), status: 'scheduled' },
        { id: 'p2', title: 'Ornament making — behind the scenes', caption: 'A peek at how each Christmas ornament gets its name ✨', type: 'video', category: 'christmas', platforms: ['instagram', 'tiktok', 'youtube', 'facebook'], scheduledAt: isoInDays(2, 18, 0), status: 'scheduled' },
        { id: 'p3', title: 'Custom name hoodies restock', caption: 'They’re back! Cozy custom hoodies in five new colours…', type: 'photo', category: 'apparel', platforms: ['instagram', 'facebook', 'pinterest'], scheduledAt: isoInDays(4, 12, 0), status: 'scheduled' },
        { id: 'p4', title: 'Holiday craft fair announcement', caption: 'Come see us this weekend! Booth details and fair hours inside 🎄', type: 'photo', category: 'event', platforms: ['facebook', 'instagram'], scheduledAt: isoInDays(5, 9, 0), status: 'attention' },
        { id: 'p5', title: 'Gift guide: under $30', caption: 'Thoughtful handmade gifts that won’t break the bank…', type: 'carousel', category: 'gifts', platforms: ['pinterest', 'instagram'], scheduledAt: isoInDays(7, 19, 30), status: 'draft' }
      ],
      activity: [
        { level: 'success', platform: 'instagram', message: 'Reel “Vinyl pressing in slow motion” published', at: isoInDays(0, 9, 2) },
        { level: 'error',   platform: 'tiktok',    message: 'TikTok upload failed — connection expired. Reconnect TikTok and retry.', at: isoInDays(-1, 18, 1) },
        { level: 'success', platform: 'facebook',  message: 'Post “Fall mug collection” published', at: isoInDays(-1, 12, 0) },
        { level: 'warning', platform: 'instagram', message: 'Craft fair post needs a cover image before it can be scheduled', at: isoInDays(-2, 16, 40) },
        { level: 'success', platform: 'pinterest', message: 'Pin “Personalized wine tumblers” published', at: isoInDays(-3, 20, 15) }
      ]
    };
  }

  return { dashboard: dashboard };
})();

